      <h1 className="text-2xl font-semibold">Create an account</h1>

      <form onSubmit={handleSubmit} className="flex flex-col gap-3">
        <input
          type="text"
          required
          autoComplete="name"
          placeholder="Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="rounded border border-black/[.15] bg-transparent px-3 py-2 dark:border-white/[.2]"
        />
        <input
          type="email"
          required
          autoComplete="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="rounded border border-black/[.15] bg-transparent px-3 py-2 dark:border-white/[.2]"
        />
        <input
          type="password"
          required
          autoComplete="new-password"
          minLength={8}
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="rounded border border-black/[.15] bg-transparent px-3 py-2 dark:border-white/[.2]"
        />
        {error && <p className="text-sm text-red-600">{error}</p>}
        <button
          type="submit"
          disabled={loading}
          className="rounded bg-foreground px-4 py-2 text-background disabled:opacity-50"
        >
          {loading ? "Creating account…" : "Sign up"}
        </button>
      </form>

      <div className="flex items-center gap-3 text-xs uppercase opacity-50">
        <span className="h-px flex-1 bg-current" />
        or
        <span className="h-px flex-1 bg-current" />
      </div>

      <button
        type="button"
        onClick={handleGoogle}
        className="rounded border border-black/[.15] px-4 py-2 dark:border-white/[.2]"
      >
        Continue with Google
      </button>

      <p className="text-sm opacity-70">
        Already have an account?{" "}
        <Link href="/sign-in" className="underline">
          Sign in
        </Link>
      </p>
    </main>
  );
}

