import { betterAuth } from "better-auth";
import { memoryAdapter, type MemoryDB } from "better-auth/adapters/memory";

// Process-memory store for this scaffold — zero setup, no native deps, and
// it resets whenever the server restarts. Swap it for a real database by
// replacing `memoryAdapter(authStore)` below with e.g. a Postgres/SQLite
// adapter; nothing else in the app needs to change, since src/lib/users.ts
// only talks to Better Auth's API, not to this store directly.
export const authStore: MemoryDB = {
  user: [],
  session: [],
  account: [],
  verification: [],
};

const googleClientId = process.env.GOOGLE_CLIENT_ID;
const googleClientSecret = process.env.GOOGLE_CLIENT_SECRET;

export const auth = betterAuth({
  database: memoryAdapter(authStore),
  baseURL: process.env.BETTER_AUTH_URL,
  secret: process.env.BETTER_AUTH_SECRET,
  emailAndPassword: {
    enabled: true,
  },
  // Only registered when both env vars are set, so the placeholder values in
  // .env.example don't break email/password auth for anyone who hasn't
  // configured a real Google OAuth client yet.
  socialProviders:
    googleClientId && googleClientSecret
      ? {
          google: {
            clientId: googleClientId,
            clientSecret: googleClientSecret,
          },
        }
      : undefined,
});

