import { headers } from "next/headers";
import { auth, db } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Backed by Better Auth's `user` table (see src/lib/auth.ts) instead of a
// hardcoded array — every account created via sign-up shows up here.
type UserRow = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

function toUser(row: UserRow): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name,
    createdAt: row.createdAt,
  };
}

export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare("SELECT id, email, name, createdAt FROM user ORDER BY createdAt ASC")
    .all() as UserRow[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db
    .prepare("SELECT id, email, name, createdAt FROM user WHERE id = ?")
    .get(id) as UserRow | undefined;
  return row ? toUser(row) : undefined;
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  return session ? toUser(session.user as UserRow) : undefined;
}

