import { headers } from "next/headers";
import { auth, authStore } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Backed by Better Auth's user store (see src/lib/auth.ts) instead of a
// hardcoded array — every account created via sign-up shows up here.
type AuthUserRecord = {
  id: string;
  email: string;
  name: string;
  createdAt: string | Date;
};

function toUser(record: AuthUserRecord): User {
  return {
    id: record.id,
    email: record.email,
    name: record.name,
    createdAt:
      record.createdAt instanceof Date
        ? record.createdAt.toISOString()
        : record.createdAt,
  };
}

export async function listUsers(): Promise<User[]> {
  const records = (authStore.user ?? []) as AuthUserRecord[];
  return records.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const records = (authStore.user ?? []) as AuthUserRecord[];
  const record = records.find((u) => u.id === id);
  return record ? toUser(record) : undefined;
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  return session ? toUser(session.user) : undefined;
}

